enum Category {EDU, HEALTH, ENV, ART}
contract CampaignRegistry{
    bytes32 public code;
    Category public category;
    uint public totalDonated;
    constructor(bytes32 campaignCode, Category categoryChoice){
        code = campaignCode;
        category = categoryChoice;
    }
    function isHealth() external view 
        returns (bool)
    { return category == Category.HEALTH;}
}

contracts/CampaignRoster.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract CampaignRoster{
    uint[] public campaignIds;

    function open(uint campaignId) external{
        campaignIds.push(campaignId);
    }

    function closeLast() external {
        require(campaignIds.length > 0);
        campaignIds.pop();
    }

    function swapRemove(uint index) external {
        campaignIds[index] = campaignIds[campaignIds.length - 1];
        campaignIds.pop();
    }
}

